def count_triples(n, R, B):
    """
    Calculates the total number of triples (x, y, z) such that:
    1. x, y, z are of the same color (Red or Blue).
    2. x + y + z is divisible by n.
    """
    count_r = 0
    # Count Red triples
    for x in R:
        for y in R:
            for z in R:
                if (x + y + z) % n == 0:
                    count_r += 1

    count_b = 0
    # Count Blue triples
    for x in B:
        for y in B:
            for z in B:
                if (x + y + z) % n == 0:
                    count_b += 1

    return count_r + count_b

target = 2007
print(f"Target count: {target}")

# Re-running the search over a larger range based on quadratic growth estimate (n ~ 90)
n_start = 40
n_end = 100
results = {}

for n in range(n_start, n_end + 1):
    # Test simple symmetric coloring: R gets the first floor(n/2) elements
    r_size = n // 2
    R = set(range(1, r_size + 1))
    B = set(range(r_size + 1, n + 1))

    count = count_triples(n, R, B)
    results[n] = count

    if count == target:
        print(f"\nSUCCESS! Found match at n={n} with count={count}")
        break

print("\n--- Results for n up to 100 ---")
# Print relevant findings for documentation
for n in range(40, 101, 5):
    print(f"n={n}: Count = {results.get(n, 'N/A')}")
